    // -------------------------------------------------------------------------
    // Viewport
    // -------------------------------------------------------------------------

    /** Set the graphpaper bounds. Invalid bounds (`right <= left` or `top <= bottom`) are ignored. */
    setMathBounds(bounds: MathBounds | ViewportBounds): void;

    /** Whether the projection is uniform (square math aspect ratio). */
